ent_hash":{"type":"text"},"access_scope":{"type":"enum","enum":"access_scopes"},"language":{"type":"text"}}},"Claim":{"idField":"claim_id","fields":{"claim_id":{"type":"id","required":true},"source_id":{"type":"ref","ref":"SourceDocument"},"subject_id":{"type":"any_ref"},"predicate":{"type":"enum","enum":"claim_predicates"},"value":{"type":"json"},"unit":{"type":"text"},"currency":{"type":"currency"},"effective_at":{"type":"datetime"},"observed_at":{"type":"datetime"},"evidence_excerpt":{"type":"text"},"assertion_type":{"type":"enum","enum":"assertion_types"},"evidence_confidence":{"type":"probability"},"review_state":{"type":"enum","enum":"review_states"},"supersedes_claim_id":{"type":"ref","ref":"Claim"}}},"StateTransition":{"idField":"transition_id","fields":{"transition_id":{"type":"id","required":true},"event_id":{"type":"ref","ref":"CorporateEvent"},"dimension":{"type":"enum","enum":"state_dimensions"},"prior_value":{"type":"json"},"new_value":{"type":"json"},"effective_at":{"type":"datetime"},"recorded_at":{"type":"datetime"},"actor":{"type":"text"},"reason":{"type":"enum","enum":"transition_reasons"},"supporting_claim_ids":{"type":"array","items":"ref","ref":"Claim"},"supersedes_transition_id":{"type":"ref","ref":"StateTransition"},"workstream_id":{"type":"ref","ref":"WorkstreamInstance"}}},"Forecast":{"idField":"forecast_id","fields":{"forecast_id":{"type":"id","required":true},"event_id":{"type":"ref","ref":"CorporateEvent"},"as_of":{"type":"datetime"},"horizon":{"type":"enum","enum":"forecast_horizons"},"target":{"type":"enum","enum":"forecast_targets"},"estimate":{"type":"json"},"low":{"type":"json"},"high":{"type":"json"},"model_version":{"type":"text"},"assumptions":{"type":"json"},"approval_state":{"type":"enum","enum":"approval_states"},"estimate_unit":{"type":"enum","enum":"forecast_units"},"date_precision":{"type":"enum","enum":"date_precisions"}}},"Feedback":{"idField":"feedback_id","fields":{"feedback_id":{"type":"id","required":true},"target_type":{"type":"enum","enum":"feedback_targets"},"target_id":{"type":"any_ref"},"proposed_value":{"type":"json"},"corrected_value":{"type":"json"},"reason":{"type":"text"},"annotator_role":{"type":"enum","enum":"annotator_roles"},"created_at":{"type":"datetime"},"adjudication":{"type":"enum","enum":"feedback_adjudications"},"ontology_version":{"type":"enum","enum":"ontology_versions"}}},"Opportunity":{"idField":"opportunity_id","fields":{"opportunity_id":{"type":"id","required":true},"event_id":{"type":"ref","ref":"CorporateEvent"},"client_entity_id":{"type":"ref","ref":"Entity"},"exposure_id":{"type":"ref","ref":"RiskExposure"},"product_family":{"type":"enum","enum":"product_families"},"evidence_status":{"type":"enum","enum":"evidence_statuses"},"urgency":{"type":"enum","enum":"urgencies"},"potential_notional":{"type":"decimal"},"commercial_owner":{"type":"enum","enum":"owner_roles"},"next_action":{"type":"enum","enum":"advisory_actions"},"decision_deadline":{"type":"datetime"},"status":{"type":"enum","enum":"opportunity_statuses"},"exposure_status":{"type":"enum","enum":"exposure_statuses"},"rationale_codes":{"type":"array","items":"enum","enum":"rationale_codes"},"ficc_score":{"type":"score"}}},"EventJurisdiction":{"idField":"jurisdiction_id","fields":{"jurisdiction_id":{"type":"id","required":true},"event_id":{"type":"ref","ref":"CorporateEvent"},"country":{"type":"country"},"nexus_entity_id":{"type":"ref","ref":"Entity"},"nexus_claim_id":{"type":"ref","ref":"Claim"},"nexus_role":{"type":"enum","enum":"nexus_roles"}}},"EventTypeTag":{"idField":"tag_id","fields":{"tag_id":{"type":"id","required":true},"event_id":{"type":"ref","ref":"CorporateEvent"},"event_type_id":{"type":"enum","enum":"event_types"}}},"EventEntityPerimeter":{"idField":"allocation_id","fields":{"allocation_id":{"type":"id","required":true},"perimeter_id":{"type":"ref","ref":"TransactionPerimeter"},"entity_id":{"type":"ref","ref":"Entity"},"included":{"type":"boolean"}}},"ExposureLegAllocation":{"idField":"allocation_id","fields":{"allocation_id":{"type":"id","required":true},"exposure_id":{"type":"ref","ref":"RiskExposure"},"leg_id":{"type":"ref","ref":"EconomicLeg"},"allocated_notional":{"type":"decimal"},"currency":{"type":"currency"}}},"HedgeExposureAllocation":{"idField":"allocation_id","fields":{"allocation_id":{"type":"id","required":true},"hedge_id":{"type":"ref","ref":"Hedge"},"exposure_id":{"type":"ref","ref":"RiskExposure"},"allocated_notional":{"type":"decimal"},"currency":{"type":"currency"}}},"ClaimSupport":{"idField":"support_id","fields":{"support_id":{"type":"id","required":true},"target_type":{"type":"enum","enum":"feedback_targets"},"target_id":{"type":"any_ref"},"claim_id":{"type":"ref","ref":"Claim"}}},"EventSource":{"idField":"event_source_id","fields":{"event_source_id":{"type":"id","required":true},"event_id":{"type":"ref","ref":"CorporateEvent"},"source_id":{"type":"ref","ref":"SourceDocument"}}}},"supplemental_enum_note":"Core enums copied verbatim from supplied JSON; dimension IDs are stable uppercase mappings of the supplied design document. Supporting enums close gaps in the logical dictionary and are application-specific."}$SCHEMA$::jsonb where version='1.0.0';
create or replace function public.ce_validate_model(g jsonb) returns void language plpgsql set search_path=pg_catalog,public as $$
declare doc jsonb;k record;r jsonb;f record;identifier text;ids text[]='{}';root_found boolean=false;ev jsonb;claim jsonb;definition jsonb;support boolean;total numeric;other jsonb;choices jsonb;
begin
 select schema_document into doc from public.corporate_event_catalogue where version='1.0.0';
 if jsonb_typeof(g)<>'object' or g->>'ontology_version' is distinct from '1.0.0' or jsonb_typeof(g->'records') is distinct from 'object' or length(g::text)>170000 then raise exception 'Invalid corporate-event model / ontology';end if;
 if exists(select 1 from jsonb_object_keys(g) key where key not in('ontology_version','root_event_id','records')) then raise exception 'Unknown model field';end if;
 for k in select * from jsonb_each(g->'records') loop
  definition=doc->'schemas'->k.key;if definition is null or jsonb_typeof(k.value)<>'array' or jsonb_array_length(k.value)>200 then raise exception 'Unknown or oversized corporate collection';end if;
  for r in select * from jsonb_array_elements(k.value) loop
   if jsonb_typeof(r)<>'object' then raise exception 'Invalid corporate record';end if;
   identifier=r->>(definition->>'idField');if identifier is null or identifier=any(ids) then raise exception 'Duplicate or missing corporate ID';end if;ids=array_append(ids,identifier);
   if k.key='CorporateEvent' and identifier=g->>'root_event_id' then root_found=true;end if;
   if exists(select 1 from jsonb_object_keys(r) key where not(definition->'fields' ? key)) then raise exception 'Unknown corporate field';end if;
   for f in select * from jsonb_each(definition->'fields') loop perform public.ce_check_field(r->f.key,f.value,r,g,doc);end loop;
   if k.key='MilestoneOccurrence' then
    select m into other from public.corporate_event_catalogue c cross join lateral jsonb_array_elements(c.catalogue->'event_templates') t cross join lateral jsonb_array_elements(t->'illustrative_milestones') m where c.version='1.0.0' and m->>'milestone_definition_id'=r->>'milestone_definition_id' limit 1;
    if other is not null and not exists(select 1 from public.corporate_event_catalogue c cross join lateral jsonb_array_elements(c.catalogue->'event_templates') t cross join lateral jsonb_array_elements(t->'illustrative_milestones') m cross join lateral jsonb_array_elements(g->'records'->'CorporateEvent') event where c.version='1.0.0' and event->>'event_id'=r->>'event_id' and t->>'event_type_id'=event->>'event_type_id' and m->>'milestone_definition_id'=r->>'milestone_definition_id') then raise exception 'Milestone template mismatch';end if;
   end if;
   if k.key='StateTransition' then
    choices=case r->>'dimension' when 'LIFECYCLE_PHASE' then doc->'enums'->'lifecycle_phases' when 'DISPOSITION' then doc->'enums'->'dispositions' when 'OUTCOME' then doc->'enums'->'outcomes' else null end;
    if r->>'dimension'='WORKSTREAM_STATUS' then select doc->'workstreams'->(w->>'workstream_type') into choices from jsonb_array_elements(g->'records'->'WorkstreamInstance') w where w->>'workstream_id'=r->>'workstream_id';end if;
    if (r->>'new_value' is not null and not coalesce(choices ? (r->>'new_value'),false)) or (r->>'prior_value' is not null and not coalesce(choices ? (r->>'prior_value'),false)) then raise exception 'Invalid transition state';end if;
   end if;
   if k.key='Forecast' and r->>'estimate_unit' is not null then
    other=jsonb_build_object('type',case r->>'estimate_unit' when 'PROBABILITY' then 'probability' when 'DATE' then 'datetime' else 'decimal' end);
    perform public.ce_check_field(r->'estimate',other,r,g,doc);perform public.ce_check_field(r->'low',other,r,g,doc);perform public.ce_check_field(r->'high',other,r,g,doc);
   end if;
   if k.key='Claim' and r->'value' is not null and r->'value'<>'null'::jsonb then
    choices=case r->>'predicate' when 'EVENT_TYPE' then doc->'enums'->'event_types' when 'LIFECYCLE_PHASE' then doc->'enums'->'lifecycle_phases' when 'FUNDING_STATUS' then doc->'enums'->'funding_certainties' when 'MILESTONE_STATUS' then doc->'enums'->'milestone_statuses' when 'CONDITION_STATUS' then doc->'enums'->'condition_states' when 'PARTY_ROLE' then doc->'enums'->'party_roles' when 'CONSIDERATION_CURRENCY' then doc->'enums'->'iso_currencies' when 'BUYER_FUNDING_CURRENCY' then doc->'enums'->'iso_currencies' when 'SELLER_PROCEEDS_CURRENCY' then doc->'enums'->'iso_currencies' else null end;
    if choices is not null and (jsonb_typeof(r->'value')<>'string' or not(choices ? (r->>'value'))) then raise exception 'Invalid predicate value enum';end if;
    if r->>'predicate'='EVENT_COMPLETION' and jsonb_typeof(r->'value')<>'boolean' then raise exception 'Completion claim must be boolean';end if;
   end if;
   for other in select * from jsonb_array_elements('[["expected_close_start","expected_close_end"],["expected_settlement_start","expected_settlement_end"],["effective_from","effective_to"],["valid_from","valid_to"],["start_at","end_at"],["exclusivity_start","exclusivity_end"]]'::jsonb) loop
    if (r->>(other->>0))::timestamptz>(r->>(other->>1))::timestamptz then raise exception 'Inverted date window';end if;
   end loop;
   if (r->>'allocated_notional')::numeric<0 then raise exception 'Negative allocation';end if;
   if k.key='HedgeExposureAllocation' and r->>'allocated_notional' is not null and exists(select 1 from jsonb_array_elements(g->'records'->'Hedge') h where h->>'hedge_id'=r->>'hedge_id' and h->>'notional_currency' is not null and r->>'currency' is not null and h->>'notional_currency'<>r->>'currency') then raise exception 'Allocation must use contract notional currency';end if;
   if k.key in('Hedge','RiskExposure','FundingInstrument') and ((r->>'notional')::numeric<0 or (r->>'committed_amount')::numeric<0 or (r->>'drawn_amount')::numeric<0) then raise exception 'Negative financial notional';end if;
   if k.key='Condition' and r->>'state'='WAIVED' and (r->>'waiver_permitted')::boolean=false then raise exception 'Condition waiver is not permitted';end if;
   if k.key='EconomicLeg' then
    if (r->>'amount_min')::numeric<0 or (r->>'amount_base')::numeric<0 or (r->>'amount_max')::numeric<0 or (r->>'amount_min')::numeric>(r->>'amount_base')::numeric or (r->>'amount_base')::numeric>(r->>'amount_max')::numeric or (r->>'amount_min')::numeric>(r->>'amount_max')::numeric then raise exception 'Invalid economic amount range';end if;
   end if;
   if k.key='EventRelationship' and r->>'from_event_id'=r->>'to_event_id' then raise exception 'Self relationship';end if;
   if k.key='ClaimSupport' and not public.ce_ref_exists(g,r->>'target_id',r->>'target_type') then raise exception 'Claim support type mismatch';end if;
   if k.key='Forecast' and r->>'target'='COMPLETION_PROBABILITY' then
    if r->>'estimate_unit' is not null and r->>'estimate_unit'<>'PROBABILITY' then raise exception 'Probability requires its own unit';end if;
    perform public.ce_check_field(r->'estimate','{"type":"probability"}',r,g,doc);perform public.ce_check_field(r->'low','{"type":"probability"}',r,g,doc);perform public.ce_check_field(r->'high','{"type":"probability"}',r,g,doc);
   end if;
   if k.key='CorporateEvent' then
    if r->>'model_version' is not null and r->>'model_version'<>'1.0.0' then raise exception 'Event version mismatch';end if;
   end if;
   if k.key='Hedge' then
    if coalesce(jsonb_array_length(r->'currencies'),0)<>(select count(distinct c) from jsonb_array_elements(coalesce(r->'currencies','[]')) c) then raise exception 'Hedge currencies must be distinct';end if;
    if r->>'product' in('FX_FORWARD','FX_OPTION','CONTINGENT_FX','CROSS_CURRENCY_SWAP') and coalesce(jsonb_array_length(r->'currencies'),0)>0 and jsonb_array_length(r->'currencies')<>2 then raise exception 'FX hedge requires a base and quote currency';end if;
    if r->>'product' in('IRS','RATE_CAP','RATE_COLLAR','INFLATION_SWAP','COMMODITY_HEDGE') and coalesce(jsonb_array_length(r->'currencies'),0)>1 then raise exception 'This hedge product uses one currency';end if;
    if r->>'notional_currency' is not null and coalesce(jsonb_array_length(r->'currencies'),0)>0 and not(r->'currencies' ? (r->>'notional_currency')) then raise exception 'Notional currency must belong to hedge currencies';end if;
   end if;
   if k.key='Hedge' then select sum((a->>'allocated_notional')::numeric) into total from jsonb_array_elements(g->'records'->'HedgeExposureAllocation') a where a->>'hedge_id'=r->>'hedge_id' and a->>'currency'=r->>'notional_currency';if total>(r->>'notional')::numeric then raise exception 'Hedge over-allocation';end if;end if;
  end loop;
 end loop;
 for f in select * from (values('EconomicLeg','leg_id','parent_leg_id'),('Claim','claim_id','supersedes_claim_id'),('MilestoneOccurrence','milestone_occurrence_id','supersedes_occurrence_id'),('StateTransition','transition_id','supersedes_transition_id')) m(kind,idkey,parentkey) loop
  if exists(with recursive edges as(select node->>f.idkey a,node->>f.parentkey b from jsonb_array_elements(g->'records'->f.kind) node where node->>f.parentkey is not null),walk(a,b,path,cycle) as(select a,b,array[a,b],a=b from edges union all select w.a,e.b,w.path||e.b,e.b=any(w.path) from walk w join edges e on e.a=w.b where not w.cycle and cardinality(w.path)<502) select 1 from walk where cycle) then raise exception 'Cyclic parent/supersession relationship';end if;
 end loop;
 if exists(with recursive edges as(select d->>'predecessor_id' a,d->>'successor_id' b from jsonb_array_elements(g->'records'->'Dependency') d),walk(a,b,path,cycle) as(select a,b,array[a,b],a=b from edges union all select w.a,e.b,w.path||e.b,e.b=any(w.path) from walk w join edges e on e.a=w.b where not w.cycle and cardinality(w.path)<502) select 1 from walk where cycle) then raise exception 'Cyclic dependency graph';end if;
 if not root_found or cardinality(ids)>500 then raise exception 'Missing root or oversized model';end if;
end $$;
create or replace function public.submit_corporate_review(p_source text,p_graph jsonb,p_note text,p_existing text,p_expected integer,p_expected_model integer,p_update_classification text,p_learning boolean,p_review_input jsonb default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare item public.source_items;mid text;current_model public.corporate_event_models;root jsonb;rev integer;source_rev integer;score integer;oid uuid;updating boolean;correcting boolean;doc jsonb;k record;r jsonb;old_r jsonb;field text;original jsonb;proposed jsonb;group_id text;old_learning text;
begin
 if not exists(select 1 from public.pilot_members where user_id=auth.uid() and enabled and can_review) then raise exception 'Reviewer access required';end if;
 select * into item from public.source_items where id=p_source for update;
 if not found or item.state not in('pending','approved') then raise exception 'Source is not editable';end if;
 if p_expected is null or item.review_version<>p_expected then raise exception 'Review changed since you opened it';end if;
 if length(coalesce(p_note,''))>1000 or length(coalesce(p_review_input::text,''))>170000 then raise exception 'Review metadata too large';end if;
 if p_update_classification is null or p_update_classification not in('UNKNOWN','MATERIAL_UPDATE','NO_MATERIAL_CHANGE') then raise exception 'Invalid update classification';end if;
 correcting=item.state='approved';if correcting and length(trim(coalesce(p_note,'')))<8 then raise exception 'Explain the correction in at least 8 characters';end if;
 perform public.ce_validate_model(p_graph);
 if exists(select 1 from jsonb_array_elements(p_graph->'records'->'CorporateEvent') event where coalesce(event->>'event_type_id','')='' or coalesce(event->>'lifecycle_phase','')='' or coalesce(event->>'disposition','')='') then raise exception 'Event type, lifecycle phase and disposition are required';end if;
 if not exists(select 1 from jsonb_array_elements(p_graph->'records'->'SourceDocument') s where s->>'url_or_internal_ref'=item.url and (s->>'publication_at')::timestamptz=item.published_at) then raise exception 'Review must retain the current source URL and publication time';end if;
 mid=case when correcting then item.corporate_model_id else coalesce(p_existing,'event-'||md5(item.id)) end;
 if correcting and p_existing is not null and p_existing<>mid then raise exception 'A historical correction cannot relink its event';end if;
 select * into current_model from public.corporate_event_models where model_id=mid for update;
 updating=not correcting or item.corporate_model_revision=current_model.revision;
 if updating and p_expected_model is distinct from coalesce(current_model.revision,0) then raise exception 'Event model changed in another session';end if;
 if not correcting and p_existing is not null and current_model.model_id is null then raise exception 'Unknown corporate model';end if;
 original=case when correcting then item.analysis else current_model.graph end;
 if updating then rev=public.ce_write_model(mid,p_graph,item.id);else rev=current_model.revision;end if;
 source_rev=item.review_version+1;
 insert into public.corporate_source_reviews(source_id,version,model_id,graph,previous_graph,model_revision,reviewer_id,note,review_input,update_classification,source_snapshot) values(item.id,source_rev,mid,p_graph,original,case when updating then rev else null end,auth.uid(),coalesce(p_note,''),p_review_input,p_update_classification,jsonb_build_object('headline',item.headline,'excerpt',item.excerpt,'url',item.url,'published_at',item.published_at,'observed_at',now()));
 select schema_document into doc from public.corporate_event_catalogue where version='1.0.0';
 proposed=coalesce(p_review_input->'original',original);
 for k in select * from jsonb_each(p_graph->'records') loop for r in select * from jsonb_array_elements(k.value) loop
  select old into old_r from jsonb_array_elements(coalesce(proposed->'records'->k.key,'[]')) old where old->>(doc->'schemas'->k.key->>'idField')=r->>(doc->'schemas'->k.key->>'idField');
  for field in select jsonb_object_keys(coalesce(old_r,'{}')||r) loop if old_r->field is distinct from r->field then
   insert into public.corporate_field_feedback(source_id,source_version,ontology_version,entity_type,record_id,field,proposed_value,corrected_value,reviewer_id,reason) values(item.id,source_rev,'1.0.0',k.key,r->>(doc->'schemas'->k.key->>'idField'),field,old_r->field,r->field,auth.uid(),coalesce(p_note,''));
  end if;end loop;
 end loop;end loop;
 for k in select * from jsonb_each(coalesce(proposed->'records','{}')) loop for old_r in select * from jsonb_array_elements(k.value) loop
  if not exists(select 1 from jsonb_array_elements(coalesce(p_graph->'records'->k.key,'[]')) current_record where current_record->>(doc->'schemas'->k.key->>'idField')=old_r->>(doc->'schemas'->k.key->>'idField')) then
   insert into public.corporate_field_feedback(source_id,source_version,ontology_version,entity_type,record_id,field,proposed_value,corrected_value,reviewer_id,reason) values(item.id,source_rev,'1.0.0',k.key,old_r->>(doc->'schemas'->k.key->>'idField'),'__record__',old_r,null,auth.uid(),coalesce(p_note,''));
  end if;
 end loop;end loop;
 update public.source_items set state='approved',analysis=p_graph,corporate_model_id=mid,corporate_model_revision=case when updating then rev else corporate_model_revision end,review_version=source_rev,reviewed_by=auth.uid(),reviewed_at=now() where id=item.id;
 select coalesce(max((o->>'ficc_score')::integer),0) into score from jsonb_array_elements(p_graph->'records'->'Opportunity') o;
 select e into root from jsonb_array_elements(p_graph->'records'->'CorporateEvent') e where e->>'event_id'=p_graph->>'root_event_id';
 if not correcting then
  insert into public.corporate_announcements(id,model_id,source_id,headline,url,published_at,update_classification) values(item.id,mid,item.id,item.headline,item.url,item.published_at,p_update_classification);
  if p_update_classification='MATERIAL_UPDATE' and score>=3 and item.published_at>=now()-interval '24 hours' then
   insert into public.notification_outbox(event_id,payload) values(item.id,jsonb_build_object('title',root->>'title','body',coalesce(root->>'event_type_id','Corporate event')||' · '||coalesce(root->>'lifecycle_phase','Unknown lifecycle'),'url','/?event='||mid,'expiresAt',item.published_at+interval '24 hours')) returning id into oid;
   insert into public.notification_deliveries(outbox_id,subscription_id) select oid,s.id from public.push_subscriptions s join public.pilot_members m on m.user_id=s.user_id where s.enabled and m.enabled and s.min_score<=score;
  end if;
 else update public.corporate_announcements set update_classification=p_update_classification where id=item.id;
 update public.notification_deliveries d set status='dead',last_error='Assessment corrected before delivery',lease_until=null where d.outbox_id in(select id from public.notification_outbox where event_id=item.id) and d.status in('queued','retry','sending');end if;
 if p_learning then
  select e->>'programme_id' into group_id from jsonb_array_elements(p_graph->'records'->'CorporateEvent') e where e->>'event_id'=p_graph->>'root_event_id';
  insert into public.review_feedback(source_id,reviewer_id,decision,reason,score,note,source_snapshot,analysis_snapshot,changed_fields) values(item.id,auth.uid(),case when score=0 then 'exclude' when score>=3 then 'useful' else 'not_useful' end,case when score=0 then 'other' when correcting then 'correction' else 'approved' end,nullif(score,0),coalesce(p_note,''),jsonb_build_object('headline',item.headline,'excerpt',item.excerpt,'url',item.url,'published_at',item.published_at,'programme_id',case when group_id is null then mid else mid||'/'||group_id end,'model_id',mid,'ontology_version','1.0.0'),p_graph,coalesce((select array_agg(distinct feedback.entity_type||'.'||feedback.field) from public.corporate_field_feedback feedback where feedback.source_id=item.id and feedback.source_version=source_rev),'{}'::text[]));
  if correcting or exists(select 1 from public.learning_settings settings join public.learning_models model on model.id=settings.active_model where settings.id=1 and settings.use_learned_ranking and model.artifact->'examples' @> jsonb_build_array(jsonb_build_object('sourceId',item.id))) then
   update public.learning_settings set use_learned_ranking=false,updated_by=auth.uid(),updated_at=now() where id=1 and use_learned_ranking returning active_model into old_learning;
   if old_learning is not null then insert into public.learning_activation_log(model_id,enabled,reviewer_id) values(old_learning,false,auth.uid());end if;
  end if;
 end if;
 delete from public.corporate_review_drafts where source_id=item.id and reviewer_id=auth.uid();
 return jsonb_build_object('saved',true,'modelId',mid,'correction',correcting,'latestModelUpdated',updating,'reviewVersion',source_rev,'modelRevision',rev,'queued',oid is not null);
end $$;
insert into public.monitor_state(key,value) values('manual_review_version','1') on conflict(key) do update set value=excluded.value;
commit;
